    ($SATQ$6585d841$SATQ$, $SATQ$cf2ac41c-6770-4663-bc5c-fdcc886db696$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Geometry and Trigonometry$SATQ$, $SATQ$S$SATQ$, $SATQ$S.D.$SATQ$, $SATQ$Circles$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: center;"><math alttext="x squared plus 14 x plus y squared equals 6 y plus 109"><mrow>
